import { describe, expect, it } from "vitest";
import { isYouTubeTopicAccount } from "@/lib/vault/isYouTubeTopicAccount";

describe("isYouTubeTopicAccount", () => {
  it.each(["Grimes - Topic", "Grimes - Topic - YouTube", "Grimes – Topic | YouTube"])(
    "rejects explicit Topic channel titles: %s",
    title => {
      expect(isYouTubeTopicAccount("youtubechannel", title)).toBe(true);
    },
  );
  it.each(["Grimes - YouTube", "Topic - YouTube", "A topic with Grimes - YouTube", null])(
    "does not confuse an artist's ordinary name or topic discussion with an autogenerated account: %s",
    title => {
      expect(isYouTubeTopicAccount("youtube", title)).toBe(false);
    },
  );
  it("does not apply the YouTube title rule to other services", () => {
    expect(isYouTubeTopicAccount("instagram", "Grimes - Topic")).toBe(false);
  });
});
